from queue import Queue
from threading import Thread, current_thread
from time import sleep
FIN = object()

def consumir(cola):
    while True:
        trabajo = cola.get()
        try:
            if trabajo is FIN:
                return
            sleep(0.05 * (1 + trabajo % 3))
            print(current_thread().name, "termina", trabajo)
        except Exception as error:
            print("Error:", error)
        finally:
            cola.task_done()

cola = Queue(maxsize=3)
consumidores = [
    Thread(target=consumir, args=(cola,), name=f"Operario {n}")
    for n in range(1, 3)
]
for hilo in consumidores:
    hilo.start()
for trabajo in range(1, 7):
    cola.put(trabajo)
for _ in consumidores:
    cola.put(FIN)
cola.join()
for hilo in consumidores:
    hilo.join()
print("Cola atendida y trabajadores finalizados")

